export const EXTRA_BASE_FONTS = [
  {id:"inter",family:"Inter",label:"Inter",category:"sans",weights:[100,200,300,400,500,600,700,800,900]},
  {id:"cascadia-mono",family:"Cascadia Mono",label:"Cascadia Mono",category:"mono",weights:[400,700]}
];

/** Labels for the category filters; the catalog contains 100 additional families. */
export const FONT_GROUPS = Object.freeze({sans: 'Sans serif', serif: 'Serif', mono: 'Monoespaciadas', display: 'Display'});
export const DEFAULT_FONTS = Object.freeze({primary: 'Space Grotesk', secondary: 'Inter', tertiary: 'Cascadia Mono'});

const knownFonts = new Map([...FONT_CATALOG, ...EXTRA_BASE_FONTS].map(font => [font.family, font]));
const requests = new Map();
const localFaces = new Map();
const remoteStyles = new Map();
const customFaces = new Map();
const SAMPLE = 'WERTBAU ÁÉÍÓÚÑ áéíóúñ ü 0123456789 ¿¡';
const FONT_TIMEOUT = 20000;

function browser() {
  if (typeof document === 'undefined' || typeof FontFace === 'undefined' || !document.fonts) {
    throw new Error('Este navegador no permite cargar archivos tipográficos.');
  }
}

function timeout(promise, message, milliseconds = FONT_TIMEOUT) {
  let timer;
  return Promise.race([
    promise,
    new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(message)), milliseconds); })
  ]).finally(() => clearTimeout(timer));
}

function quoteFamily(family) {
  return '"' + family.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}

function nearestWeight(weights, value) {
  const requested = Number(value);
  const wanted = Number.isFinite(requested) ? requested : 400;
  return weights.reduce((best, current) => Math.abs(current - wanted) < Math.abs(best - wanted) ? current : best, weights[0]);
}

/** Resolve to a weight that is actually supplied, without pretending a synthetic weight is a font file. */
export function resolveFontWeight(family, weight = 400) {
  const customs = [...customFaces.values()].filter(font => font.family === family);
  if (customs.length) return nearestWeight(customs.map(font => font.weight), weight);
  const definition = knownFonts.get(family);
  if (definition) return nearestWeight(definition.weights, weight);
  return Math.max(100, Math.min(900, Number(weight) || 400));
}

export function getFontDefinition(family) {
  return knownFonts.get(family) || null;
}

/** The URL of the bundled, full-glyph WOFF2 file; useful when exporting a self-contained project. */
export function getBundledFont(family, weight = 400) {
  const definition = knownFonts.get(family);
  if (!definition) return null;
  const actualWeight = nearestWeight(definition.weights, weight);
  const filename = `${definition.id}-${actualWeight}.woff2`;
  return {
    family,
    weight: actualWeight,
    file: filename,
    url: new URL(`../assets/fonts/${filename}`, import.meta.url).href,
    format: 'woff2'
  };
}

async function localFont(family, weight) {
  const asset = getBundledFont(family, weight);
  if (!asset) throw new Error(`No hay un archivo local de ${family}.`);
  if (!localFaces.has(asset.file)) {
    const loading = (async () => {
      const face = new FontFace(family, `url(${JSON.stringify(asset.url)}) format("woff2")`, {
        style: 'normal', weight: String(asset.weight), display: 'swap'
      });
      await timeout(face.load(), `No se pudo cargar el archivo local de ${family}.`);
      document.fonts.add(face);
      return face;
    })();
    localFaces.set(asset.file, loading);
    loading.catch(() => localFaces.delete(asset.file));
  }
  await localFaces.get(asset.file);
  return {family, weight: asset.weight, source: 'bundled', url: asset.url};
}

function remoteStyle(family, weight) {
  const key = `${family}:${weight}`;
  if (remoteStyles.has(key)) return remoteStyles.get(key);
  const promise = new Promise((resolve, reject) => {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = `https://fonts.googleapis.com/css2?family=${encodeURIComponent(family).replace(/%20/g, '+')}:wght@${weight}&display=swap`;
    link.dataset.visionFont = key;
    const timer = setTimeout(() => fail(new Error(`La carga de ${family} tardó demasiado.`)), FONT_TIMEOUT);
    function fail(error) {
      clearTimeout(timer);
      link.onload = link.onerror = null;
      link.remove();
      reject(error);
    }
    link.onload = () => {
      clearTimeout(timer);
      link.onload = link.onerror = null;
      resolve(link);
    };
    link.onerror = () => fail(new Error(`No se pudo descargar ${family}. Revisá la conexión.`));
    document.head.append(link);
  });
  remoteStyles.set(key, promise);
  promise.catch(() => remoteStyles.delete(key));
  return promise;
}

async function googleFont(family, weight) {
  await remoteStyle(family, weight);
  const loaded = await timeout(document.fonts.load(`${weight} 32px ${quoteFamily(family)}`, SAMPLE), `No se pudo descargar ${family}.`);
  if (!loaded.length || !loaded.every(face => face.status === 'loaded')) {
    throw new Error(`${family} no llegó a cargarse. La fuente anterior se mantiene.`);
  }
  return {family, weight, source: 'google'};
}

/**
 * Loads only the selected family and weight. All 100 catalog families plus Inter and Cascadia Mono
 * are bundled. Google Fonts is a fallback for a missing/damaged local asset,
 * never a prerequisite for the standard offline editor.
 * A rejected call is removed from the cache and may be retried explicitly.
 */
export async function loadFont(family, weight = 400) {
  browser();
  if (typeof family !== 'string' || !family.trim()) throw new Error('Elegí una familia tipográfica.');
  const actualWeight = resolveFontWeight(family, weight);
  const custom = [...customFaces.values()].find(font => font.family === family && font.weight === actualWeight);
  if (custom) return {family, weight: actualWeight, source: 'custom', id: custom.id};
  if (!knownFonts.has(family)) {
    throw new Error(`La fuente «${family}» no está importada. Cargá su archivo TTF, OTF, WOFF o WOFF2.`);
  }
  const key = `${family}:${actualWeight}`;
  if (!requests.has(key)) {
    const promise = localFont(family, actualWeight).catch(async localError => {
      try {
        return await googleFont(family, actualWeight);
      } catch (remoteError) {
        const error = new Error(`No se pudo cargar ${family}. Comprobá que la carpeta assets/fonts esté completa o que haya conexión a Internet.`);
        error.cause = {local: localError.message, remote: remoteError.message};
        throw error;
      }
    });
    requests.set(key, promise);
    promise.catch(() => requests.delete(key));
  }
  return requests.get(key);
}

/** Restores a locally imported font; the caller persists the supplied dataUrl. */
export async function registerCustomFont({id, family, dataUrl, weight = 400}) {
  browser();
  if (typeof id !== 'string' || !/^[A-Za-z0-9_-]{1,120}$/.test(id)) throw new Error('Identificador de fuente no válido.');
  if (typeof family !== 'string' || !family.trim() || family.length > 120 || /[\x00-\x1F"\\]/.test(family)) {
    throw new Error('El nombre de la fuente no es válido.');
  }
  if (typeof dataUrl !== 'string' || dataUrl.length > 24 * 1024 * 1024 || !/^data:(?:(?:font\/(?:ttf|otf|woff2?|sfnt)|application\/(?:octet-stream|font-woff2?|x-font-(?:ttf|otf|woff|opentype)|font-sfnt|vnd\.ms-opentype)))?;base64,[A-Za-z0-9+/=\s]+$/i.test(dataUrl)) {
    throw new Error('Importá un archivo TTF, OTF, WOFF o WOFF2 válido (máximo 18 MB).');
  }
  family = family.trim();
  const actualWeight = Math.round(Math.max(100, Math.min(900, Number(weight) || 400)));
  const face = new FontFace(family, `url(${JSON.stringify(dataUrl)})`, {style: 'normal', weight: String(actualWeight), display: 'swap'});
  try {
    await timeout(face.load(), 'El archivo tipográfico tardó demasiado en abrirse.');
  } catch (error) {
    throw new Error('El navegador no pudo abrir esta fuente. Verificá que el archivo no esté dañado.', {cause: error});
  }
  const old = customFaces.get(id);
  if (old) document.fonts.delete(old.face);
  document.fonts.add(face);
  customFaces.set(id, {id, family, weight: actualWeight, face});
  for (const key of requests.keys()) if (key.startsWith(`${family}:`)) requests.delete(key);
  return {id, family, label: family, category: 'custom', weights: [actualWeight], weight: actualWeight, source: 'custom'};
}

export async function loadBaseFonts() {
  return Promise.all([
    loadFont(DEFAULT_FONTS.primary, 600),
    loadFont(DEFAULT_FONTS.secondary, 400),
    loadFont(DEFAULT_FONTS.tertiary, 400)
  ]);
}
